// --- app.js (Main application file) ---
const express = require('express');
const cors = require('cors');
const uuidv4 = require('uuid').v4;

/**
 * In-memory data store for todos.
 * Structure: { id, title, completed, createdAt, updatedAt }
 */
let todosStore = [];

// Middleware setup
const app = express();
app.use(express.json()); // For parsing JSON request bodies
app.use(cors({ origin: '*' })); // Enable CORS for all origins

/**
 * Helper function to find a todo by ID and return it or null/throw an error.
 * @param {string} id - The ID of the todo.
 * @returns {object | undefined} The found todo object.
 */
const getTodoById = (id) => todosStore.find(todo => todo.id === id);

/**
 * GET /todos
 * Lists all todos, optionally filtered by completed status.
 * Example: ?completed=true
 */
app.get('/todos', (req, res) => {
    try {
        const { completed } = req.query;
        let filteredTodos = [...todosStore];

        if (completed !== undefined) {
            const isCompleted = completed === 'true';
            filteredTodos = todosStore.filter(todo => todo.completed === isCompleted);
        }

        res.status(200).json(filteredTodos);
    } catch (error) {
        console.error("Error listing todos:", error);
        res.status(500).json({ message: "Internal server error while fetching todos." });
    }
});

/**
 * GET /todos/:id
 * Gets a single todo by ID.
 */
app.get('/todos/:id', (req, res) => {
    const id = req.params.id;
    const todo = getTodoById(id);

    if (!todo) {
        return res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }

    res.status(200).json(todo);
});

/**
 * POST /todos
 * Creates a new todo. Validates title presence and format.
 */
app.post('/todos', (req, res) => {
    const { title } = req.body;

    // 1. Validation Check
    if (!title || typeof title !== 'string' || title.trim().length === 0) {
        return res.status(400).json({ message: "Validation failed: Title is required and must be a non-empty string." });
    }
    if (title.length > 100) {
         return res.status(400).json({ message: "Validation failed: Title cannot exceed 100 characters." });
    }

    // 2. Create and store todo
    const newTodo = {
        id: uuidv4(),
        title: title.trim(),
        completed: false, // Default value
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };

    todosStore.push(newTodo);

    // 3. Respond
    res.status(201).json(newTodo);
});


/**
 * PUT /todos/:id
 * Updates an existing todo. Validates input fields.
 */
app.put('/todos/:id', (req, res) => {
    const id = req.params.id;
    const todoIndex = todosStore.findIndex(t => t.id === id);

    if (todoIndex === -1) {
        return res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }

    const updates = req.body;
    let updatedTodo = { ...todosStore[todoIndex] };

    try {
        // Validation for Title update
        if (updates.title !== undefined) {
            const { title: newTitle } = updates;
             if (!newTitle || typeof newTitle !== 'string' || newTitle.trim().length === 0) {
                return res.status(400).json({ message: "Validation failed: Title must be a non-empty string." });
            }
            if (newTitle.length > 100) {
                 return res.status(400).json({ message: "Validation failed: Title cannot exceed 100 characters." });
            }
            updatedTodo.title = newTitle.trim();
        }

        // Validation and update for completed status
        if (typeof updates.completed !== 'undefined') {
             const isValidBoolean = typeof updates.completed === 'boolean';
             if (!isValidBoolean) {
                return res.status(400).json({ message: "Validation failed: 'completed' must be a boolean." });
            }
            updatedTodo.completed = updates.completed;
        }

        // Apply mandatory updates and store the changes
        updatedTodo.updatedAt = new Date().toISOString();
        todosStore[todoIndex] = updatedTodo;

        res.status(200).json(updatedTodo);

    } catch (error) {
        console.error("Error updating todo:", error);
        res.status(500).json({ message: "Internal server error while updating todo." });
    }
});


/**
 * DELETE /todos/:id
 * Deletes a todo by ID.
 */
app.delete('/todos/:id', (req, res) => {
    const id = req.params.id;
    const initialLength = todosStore.length;

    // Filter out the todo with the given ID
    todosStore = todosStore.filter(todo => todo.id !== id);

    if (todosStore.length === initialLength) {
        return res.status(404).json({ message: `Todo with ID ${id} not found.` });
    }

    // 204 No Content is ideal for successful deletion, but 200 with confirmation is also common.
    res.status(200).json({ message: `Todo with ID ${id} deleted successfully.` });
});


/**
 * Expose the app instance for testing purposes (Requirement #9)
 */
module.exports = { app, todosStore };

// Start server only if running directly via node command
if (require.main === module) {
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
        console.log(`🚀 Server listening on port ${PORT}`);
    });
}

